  "@id": "https://www.patronaccounting.com/ind-as/#faq",
  "datePublished": "2026-07-24T08:00:00+05:30",
  "dateModified": "2026-07-24T08:00:00+05:30",
  "mainEntity": [{"@type": "Question", "name": "What is the difference between AS and Ind AS?", "acceptedAnswer": {"@type": "Answer", "text": "AS (Accounting Standards) are the standards issued by the ICAI and applied by entities not required to adopt Ind AS. Ind AS are the IFRS-converged standards notified under the Companies (Indian Accounting Standards) Rules, 2015, and are mandatory for specified companies based on listing status and net worth."}},{"@type": "Question", "name": "Who is required to follow Ind AS?", "acceptedAnswer": {"@type": "Answer", "text": "Listed companies (and companies in the process of listing) and unlisted companies meeting the net-worth thresholds under the Companies (Ind AS) Rules must apply Ind AS, along with their holding, subsidiary, associate and joint-venture companies. Companies outside these criteria continue to apply AS."}},{"@type": "Question", "name": "How do I find the standard I need?", "acceptedAnswer": {"@type": "Answer", "text": "Use the search box at the top or browse the AS and Ind AS lists below. Each card links to a detailed guide covering the standard's scope, applicability, key requirements and disclosures."}},{"@type": "Question", "name": "Are these standards mandatory for all businesses?", "acceptedAnswer": {"@type": "Answer", "text": "Applicability depends on the type and size of the entity. Companies follow either AS or Ind AS as prescribed under the Companies Act rules; non-corporate entities generally follow the AS issued by the ICAI. Our team can confirm exactly which framework applies to you."}},{"@type": "Question", "name": "Can Patron help apply these standards to our accounts?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. Our CA & CS team handles Ind AS / AS implementation, first-time adoption, disclosures and preparation of financial statements that are compliant and audit-ready."}}]
}
